CREATE TABLE repair_requests(id UUID PRIMARY KEY,client_id UUID NOT NULL,device_id UUID NOT NULL,device_category_id UUID NOT NULL,status VARCHAR(32) NOT NULL,priority INTEGER NOT NULL CHECK(priority BETWEEN 1 AND 5),problem_description VARCHAR(1000) NOT NULL,estimated_cost DECIMAL(12,2),created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE repair_request_status_history(id UUID PRIMARY KEY,repair_request_id UUID NOT NULL REFERENCES repair_requests(id),previous_status VARCHAR(32),new_status VARCHAR(32) NOT NULL,changed_by UUID NOT NULL,changed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_request_client ON repair_requests(client_id); CREATE INDEX idx_request_status ON repair_requests(status); CREATE INDEX idx_request_created ON repair_requests(created_at); CREATE INDEX idx_request_category ON repair_requests(device_category_id);
CREATE TABLE outbox_events(event_id UUID PRIMARY KEY,topic VARCHAR(120) NOT NULL,aggregate_id UUID NOT NULL,event_type VARCHAR(100) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published BOOLEAN NOT NULL,published_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL);
